#rf-root,.hf-root{--x3:#4a5447;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 6s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.bd-grid{position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px),linear-gradient(90deg,color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px);background-size:108px 108px;background-position:-2px -2px}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx-out{transform:translateY(101%);animation:tx-out 0.5s cubic-bezier(.76,0,.24,1) 5.5s both}@keyframes tx-out{to{transform:translateY(0)}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}@property --n125{syntax:'<integer>';inherits:false;initial-value:0}
.n125{counter-reset:n125 var(--n125);animation:n125-c 3s cubic-bezier(.16,1,.3,1) 0.5s both}
.n125::after{content:counter(n125,decimal)}
@keyframes n125-c{from{--n125:0}to{--n125:168}}.land{position:absolute;inset:0}.land i{position:absolute;display:block;background:color-mix(in srgb,var(--rf-text) 5%,transparent);border:2px solid color-mix(in srgb,var(--rf-text) 9%,transparent)}
.rt{position:absolute;inset:0}
.rp{fill:none;stroke:var(--rf-accent);stroke-width:10;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:1;animation:ld 3s cubic-bezier(.76,0,.24,1) 0.5s both}
.rpd{fill:none;stroke:color-mix(in srgb,var(--rf-text) 30%,transparent);stroke-width:4;stroke-dasharray:4 18}
@keyframes ld{to{stroke-dashoffset:0}}
.pin{position:absolute;width:0;height:0;animation:k-pop .5s cubic-bezier(.16,1,.3,1) both}
.pd{position:absolute;left:-24px;top:-24px;width:48px;height:48px;border-radius:50%;background:var(--rf-text);border:10px solid var(--rf-accent)}
.pl{position:absolute;top:-30px;white-space:nowrap;font-size:42px;font-weight:600;padding:8px 22px;border-radius:16px;background:var(--rf-bg);border:2px solid color-mix(in srgb,var(--rf-text) 15%,transparent)}
.pl.r{left:50px}.pl.l{right:50px}
.rt-hd{position:absolute;left:90px;right:90px;top:200px}
.rt-t{font-size:96px;font-weight:var(--rf-heading-weight);letter-spacing:-.04em;line-height:.98}
.rt-k{margin-top:24px;font:500 46px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}

